import { View, Text, TextInput, Pressable, Alert, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [form, setForm] = useState({ name: "", phone: "" });
  const valid = form.name.trim() !== "" && form.phone.trim() !== "";
  function submit() {
    if (!valid) return;
    // энд бичнэ үү: Alert.alert("Амжилттай", ...)-аар баталгаажуул
  }
  return (
    <View style={styles.screen}>
      <TextInput nativeID="name" style={styles.input} placeholder="Нэр"
        value={form.name} onChangeText={(v) => setForm({ ...form, name: v })} />
      <TextInput nativeID="phone" style={styles.input} placeholder="Утас" keyboardType="numeric"
        value={form.phone} onChangeText={(v) => setForm({ ...form, phone: v })} />
      <Pressable nativeID="submit" style={styles.btn} onPress={submit}>
        <Text style={styles.btnText}>Захиалах</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  btn: { backgroundColor: "#16a34a", padding: 14, borderRadius: 10, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, TextInput, Pressable, Alert, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [form, setForm] = useState({ name: "", phone: "" });
  const valid = form.name.trim() !== "" && form.phone.trim() !== "";
  function submit() {
    if (!valid) return;
    Alert.alert("Амжилттай", form.name + "-ийн захиалга баталгаажлаа");
  }
  return (
    <View style={styles.screen}>
      <TextInput nativeID="name" style={styles.input} placeholder="Нэр"
        value={form.name} onChangeText={(v) => setForm({ ...form, name: v })} />
      <TextInput nativeID="phone" style={styles.input} placeholder="Утас" keyboardType="numeric"
        value={form.phone} onChangeText={(v) => setForm({ ...form, phone: v })} />
      <Pressable nativeID="submit" style={styles.btn} onPress={submit}>
        <Text style={styles.btnText}>Захиалах</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  btn: { backgroundColor: "#16a34a", padding: 14, borderRadius: 10, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
